from typing import List

class Solution:
    def sortedSquares(self, nums: List[int]) -> List[int]:
        neg = []
        pos = []
        for x in nums:
            if x < 0:
                neg.append(x * x)
            else:
                pos.append(x * x)
        neg.reverse()
        i = j = 0
        result = []
        while i < len(neg) or j < len(pos):
            if j == len(pos) or (i < len(neg) and neg[i] <= pos[j]):
                result.append(neg[i])
                i += 1
            else:
                result.append(pos[j])
                j += 1
        return result

